B.ZX=s([B.PL,B.P4,B.Pu,B.Pa,B.Q1],t.J)
B.ON=new A.e4("Recall \u2014 generalization check","gen-recall","A literal lifesaver. *If you practice off-leash, please use a safe, fenced-in location.*",B.ZX,null)
B.OY=new A.aT("course-L1W6-gen-loose-leash-p1","**Phase 1:** Indoors?")
B.P3=new A.aT("course-L1W6-gen-loose-leash-p2","**Phase 2:** In your yard?")
